import { Component, OnInit, inject } from '@angular/core';
import { WelcomeComponent } from '../welcome/welcome.component';
import { SeleccionTipoTramiteComponent } from '../externos/seleccion-tipo-tramite/seleccion-tipo-tramite.component';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';

@Component({
  standalone: true,
  selector: 'app-inicio',
  imports: [WelcomeComponent, SeleccionTipoTramiteComponent],
  templateUrl: './inicio.component.html',
  styleUrl: './inicio.component.css'
})
export class InicioComponent implements OnInit {
  userType = '';
  private localStorageService = inject(LocalStorageService);

  ngOnInit(): void {
    const userData = this.localStorageService.getUser();
    this.userType = userData?.user?.user_type || '';
  }

  isInternalUser(): boolean {
    return this.userType === 'INTERNO';
  }

  isExternalUser(): boolean {
    return this.userType === 'EXTERNO';
  }
}
