import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  standalone: true,
  imports: [CommonModule],
  selector: 'app-seleccion-tipo-tramite',
  templateUrl: './seleccion-tipo-tramite.component.html',
  styleUrl: './seleccion-tipo-tramite.component.css'
})
export class SeleccionTipoTramiteComponent {
  private readonly router = inject(Router);

  public readonly TIPO_TRAMITE_NOME = 'estimulo_nomina';
  public readonly TIPO_TRAMITE_AGUAS = 'estimulo_tratamiento_aguas';

  seleccionarTipoTramite(tipo: string): void {
    void this.router.navigate(['/main/externos/mi-empresa'], {
      queryParams: { tipoTramite: tipo }
    });
  }
}
